head.script:
// gridView advancedExcelDownload printSet.marginUnit 옵션 검증 샘플
//
// 1 inch = 2.54 cm
// 1~5 번은 모두 상단 여백 1 inch 로 생성돼야 한다.
// 6 번은 대조군으로, 단위 옵션이 실제로 동작하는지 확인한다.
//
// 확인 방법
//   Excel : 페이지 레이아웃 > 여백 > 사용자 지정 여백 (한국 Excel 은 cm 표시)
//   정확히 : XLSX 압축을 풀어 xl/worksheets/sheet1.xml 의 pageMargins 확인 (항상 inch)

scwin.onpageload = function() {
    dataList1.setJSON([
        { region: "서울", industry: "제조", amount: 100 },
        { region: "부산", industry: "서비스", amount: 200 }
    ]);
};

scwin.download = function(fileName, marginUnit, marginTop) {
    var options = {
        fileName: fileName,
        extension: "xlsx",
        showDialog: false,
        useXHR: true
    };
    var printSet = {};
    if (typeof marginUnit !== "undefined") {
        printSet.marginUnit = marginUnit;
    }
    if (typeof marginTop !== "undefined") {
        printSet.marginTop = marginTop;
    }
    options.printSet = printSet;
    gridView1.advancedExcelDownload(options);
};

// 1) 단위 미지정 + 2.54 -> 기본값이 cm 이므로 1 inch
scwin.downloadDefault = function() {
    scwin.download("marginUnit_default.xlsx", undefined, 2.54);
};

// 2) cm 명시 + 2.54 -> 1 inch (1 번과 동일해야 한다)
scwin.downloadCm = function() {
    scwin.download("marginUnit_cm.xlsx", "cm", 2.54);
};

// 3) inch 명시 + 1 -> 1 inch (변환하지 않는다)
scwin.downloadInch = function() {
    scwin.download("marginUnit_inch.xlsx", "inch", 1);
};

// 4) 대소문자 및 앞뒤 공백 허용 -> 3 번과 동일해야 한다
scwin.downloadInchLoose = function() {
    scwin.download("marginUnit_inch_loose.xlsx", "  INCH  ", 1);
};

// 5) 잘못된 값 -> cm 로 처리 -> 1 inch
scwin.downloadInvalid = function() {
    scwin.download("marginUnit_invalid.xlsx", "mm", 2.54);
};

// 6) 대조군. inch 명시 + 2.54 -> 2.54 inch 가 나와야 한다.
//    1~5 번과 같은 값이 나오면 marginUnit 이 무시되고 있다는 뜻이다.
scwin.downloadControl = function() {
    scwin.download("marginUnit_control.xlsx", "inch", 2.54);
};

// 7) 여백 0 은 유효한 값으로 보존돼야 한다
scwin.downloadZero = function() {
    scwin.download("marginUnit_zero.xlsx", "cm", 0);
};

// 8) 여백 자체를 지정하지 않으면 Excel 기본 여백을 유지해야 한다
scwin.downloadNoMargin = function() {
    scwin.download("marginUnit_no_margin.xlsx", "cm", undefined);
};
